import { useEffect, useState, useCallback } from 'react'
import { useQuery, useMutation } from '@tanstack/react-query'
import { useAuthStore, useExploreStore, useFavoritesStore } from '@/stores'
import { authService, propertiesService, favoritesService } from '@/services/api'
import type { ExploreFilters, LoginCredentials, SignupData } from '@/types'

// Auth Hook
export function useAuth() {
  const {
    user,
    isAuthenticated,
    isLoading,
    error,
    login: loginStore,
    logout: logoutStore,
    setError,
    clearError,
  } = useAuthStore()

  // Initialize auth state from localStorage
  useEffect(() => {
    const token = localStorage.getItem('accessToken')
    const userData = localStorage.getItem('user')
    
    if (token && userData) {
      try {
        const parsedUser = JSON.parse(userData)
        loginStore(parsedUser, token, localStorage.getItem('refreshToken') || '')
      } catch (error) {
        console.error('Error parsing user data:', error)
        logoutStore()
      }
    }
  }, [loginStore, logoutStore])

  const loginMutation = useMutation({
    mutationFn: (credentials: LoginCredentials) => authService.signin(credentials),
    onSuccess: (data) => {
      loginStore(data.user, data.accessToken, data.refreshToken)
      localStorage.setItem('accessToken', data.accessToken)
      localStorage.setItem('refreshToken', data.refreshToken)
      localStorage.setItem('user', JSON.stringify(data.user))
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || 'Login failed')
    },
  })

  const signupMutation = useMutation({
    mutationFn: (data: SignupData) => authService.signup(data),
    onSuccess: (data) => {
      loginStore(data.user, data.accessToken, data.refreshToken)
      localStorage.setItem('accessToken', data.accessToken)
      localStorage.setItem('refreshToken', data.refreshToken)
      localStorage.setItem('user', JSON.stringify(data.user))
    },
    onError: (error: any) => {
      setError(error.response?.data?.message || 'Signup failed')
    },
  })

  const logout = useCallback(() => {
    logoutStore()
    localStorage.removeItem('accessToken')
    localStorage.removeItem('refreshToken')
    localStorage.removeItem('user')
  }, [logoutStore])

  return {
    user,
    isAuthenticated,
    isLoading: isLoading || loginMutation.isPending || signupMutation.isPending,
    error,
    login: loginMutation.mutate,
    signup: signupMutation.mutate,
    logout,
    clearError,
  }
}

// Properties Hook
export function useProperties(filters?: ExploreFilters) {
  const { properties, setProperties, setLoading, setError } = useExploreStore()

  const {
    data,
    isLoading,
    error,
  } = useQuery({
    queryKey: ['properties', filters],
    queryFn: () => propertiesService.getAll(filters || {}),
    enabled: true,
  })

  useEffect(() => {
    if (data) {
      setProperties(data.data)
    }
  }, [data, setProperties])

  useEffect(() => {
    setLoading(isLoading)
  }, [isLoading, setLoading])

  useEffect(() => {
    if (error) {
      setError(error.message)
    }
  }, [error, setError])

  return {
    properties,
    isLoading,
    error,
    hasMore: false,
    loadMore: () => {},
    isFetchingMore: false,
  }
}

// Favorites Hook
export function useFavorites() {
  const { favorites, setFavorites, removeFavorite, isFavorite } = useFavoritesStore()

  const { data, isLoading, error } = useQuery({
    queryKey: ['favorites'],
    queryFn: favoritesService.getFavorites,
    enabled: true,
  })

  useEffect(() => {
    if (data) {
      setFavorites(data)
    }
  }, [data, setFavorites])

  const toggleFavoriteMutation = useMutation({
    mutationFn: (propertyId: string) => favoritesService.toggleFavorite(propertyId),
    onSuccess: (isFav, propertyId) => {
      // Update local state based on response
      if (!isFav) {
        removeFavorite(propertyId)
      }
    },
  })

  return {
    favorites,
    isLoading,
    error,
    isFavorite,
    toggleFavorite: toggleFavoriteMutation.mutate,
  }
}

// Geolocation Hook
export function useGeolocation() {
  const [location, setLocation] = useState<{ latitude: number; longitude: number } | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  const getCurrentPosition = useCallback(() => {
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by this browser')
      return
    }

    setIsLoading(true)
    setError(null)

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setLocation({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
        })
        setIsLoading(false)
      },
      (error) => {
        setError(error.message)
        setIsLoading(false)
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 300000, // 5 minutes
      }
    )
  }, [])

  useEffect(() => {
    getCurrentPosition()
  }, [getCurrentPosition])

  return {
    location,
    error,
    isLoading,
    getCurrentPosition,
  }
}

// Local Storage Hook
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key)
      return item ? JSON.parse(item) : initialValue
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error)
      return initialValue
    }
  })

  const setValue = useCallback(
    (value: T | ((val: T) => T)) => {
      try {
        const valueToStore = value instanceof Function ? value(storedValue) : value
        setStoredValue(valueToStore)
        window.localStorage.setItem(key, JSON.stringify(valueToStore))
      } catch (error) {
        console.error(`Error setting localStorage key "${key}":`, error)
      }
    },
    [key, storedValue]
  )

  const removeValue = useCallback(() => {
    try {
      window.localStorage.removeItem(key)
      setStoredValue(initialValue)
    } catch (error) {
      console.error(`Error removing localStorage key "${key}":`, error)
    }
  }, [key, initialValue])

  return [storedValue, setValue, removeValue] as const
}

// Debounced Value Hook
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    return () => {
      clearTimeout(handler)
    }
  }, [value, delay])

  return debouncedValue
}

// Intersection Observer Hook
export function useIntersectionObserver(
  elementRef: React.RefObject<Element>,
  options?: IntersectionObserverInit
) {
  const [isIntersecting, setIsIntersecting] = useState(false)

  useEffect(() => {
    const element = elementRef.current
    if (!element) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsIntersecting(entry.isIntersecting)
      },
      options
    )

    observer.observe(element)

    return () => {
      observer.unobserve(element)
    }
  }, [elementRef, options])

  return isIntersecting
}

// Window Size Hook
export function useWindowSize() {
  const [windowSize, setWindowSize] = useState({
    width: window.innerWidth,
    height: window.innerHeight,
  })

  useEffect(() => {
    function handleResize() {
      setWindowSize({
        width: window.innerWidth,
        height: window.innerHeight,
      })
    }

    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return windowSize
}

// Online Status Hook
export function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(navigator.onLine)

  useEffect(() => {
    function handleOnline() {
      setIsOnline(true)
    }

    function handleOffline() {
      setIsOnline(false)
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  return isOnline
}
