import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  ChevronDown, 
  X, 
  DollarSign, 
  Home, 
  MapPin, 
  Filter
} from 'lucide-react'
import type { ExploreFilters } from '@/types'

interface SearchFiltersProps {
  filters: ExploreFilters
  onFiltersChange: (filters: Partial<ExploreFilters>) => void
}

const propertyTypes = [
  { value: 'apartment', label: 'Apartment' },
  { value: 'house', label: 'House' },
  { value: 'condo', label: 'Condo' },
  { value: 'studio', label: 'Studio' },
]

const amenities = [
  'Parking',
  'Laundry',
  'Gym',
  'Pool',
  'Balcony',
  'Pet Friendly',
  'Furnished',
  'Air Conditioning',
  'Heating',
  'WiFi',
  'Dishwasher',
  'Microwave',
]

export default function SearchFilters({ filters, onFiltersChange }: SearchFiltersProps) {
  const [isExpanded, setIsExpanded] = useState(false)

  const handlePriceChange = (field: 'priceMin' | 'priceMax', value: string) => {
    const numValue = value ? parseInt(value) : undefined
    onFiltersChange({ [field]: numValue })
  }

  const handleBedroomsChange = (value: string) => {
    const numValue = value ? parseInt(value) : undefined
    onFiltersChange({ bedrooms: numValue })
  }

  const handleBathroomsChange = (value: string) => {
    const numValue = value ? parseInt(value) : undefined
    onFiltersChange({ bathrooms: numValue })
  }

  const handlePropertyTypeChange = (type: string) => {
    const currentTypes = filters.propertyType || []
    const newTypes = currentTypes.includes(type)
      ? currentTypes.filter(t => t !== type)
      : [...currentTypes, type]
    onFiltersChange({ propertyType: newTypes })
  }

  const handleAmenityChange = (amenity: string) => {
    const currentAmenities = filters.amenities || []
    const newAmenities = currentAmenities.includes(amenity)
      ? currentAmenities.filter(a => a !== amenity)
      : [...currentAmenities, amenity]
    onFiltersChange({ amenities: newAmenities })
  }

  const handleRadiusChange = (value: string) => {
    const numValue = value ? parseInt(value) : undefined
    onFiltersChange({ radius: numValue })
  }

  const clearFilters = () => {
    onFiltersChange({
      priceMin: undefined,
      priceMax: undefined,
      bedrooms: undefined,
      bathrooms: undefined,
      propertyType: [],
      amenities: [],
      radius: undefined,
    })
  }

  const getActiveFiltersCount = () => {
    let count = 0
    if (filters.priceMin || filters.priceMax) count++
    if (filters.bedrooms) count++
    if (filters.bathrooms) count++
    if (filters.propertyType?.length) count++
    if (filters.amenities?.length) count++
    if (filters.radius) count++
    return count
  }

  const activeFiltersCount = getActiveFiltersCount()

  return (
    <div className="space-y-4">
      {/* Filter Pills */}
      <div className="flex flex-wrap gap-2">
        {/* Price Range */}
        {(filters.priceMin || filters.priceMax) && (
          <div className="flex items-center bg-primary-100 text-primary-700 px-3 py-1 rounded-full text-sm">
            <DollarSign className="w-4 h-4 mr-1" />
            <span>
              ${filters.priceMin || 0} - ${filters.priceMax || '∞'}
            </span>
            <button
              onClick={() => onFiltersChange({ priceMin: undefined, priceMax: undefined })}
              className="ml-2 hover:text-primary-900"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        )}

        {/* Bedrooms */}
        {filters.bedrooms && (
          <div className="flex items-center bg-primary-100 text-primary-700 px-3 py-1 rounded-full text-sm">
            <Home className="w-4 h-4 mr-1" />
            <span>{filters.bedrooms} bedrooms</span>
            <button
              onClick={() => onFiltersChange({ bedrooms: undefined })}
              className="ml-2 hover:text-primary-900"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        )}

        {/* Bathrooms */}
        {filters.bathrooms && (
          <div className="flex items-center bg-primary-100 text-primary-700 px-3 py-1 rounded-full text-sm">
            <Home className="w-4 h-4 mr-1" />
            <span>{filters.bathrooms} bathrooms</span>
            <button
              onClick={() => onFiltersChange({ bathrooms: undefined })}
              className="ml-2 hover:text-primary-900"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        )}

        {/* Property Types */}
        {filters.propertyType?.map(type => (
          <div key={type} className="flex items-center bg-primary-100 text-primary-700 px-3 py-1 rounded-full text-sm">
            <span>{propertyTypes.find(t => t.value === type)?.label}</span>
            <button
              onClick={() => handlePropertyTypeChange(type)}
              className="ml-2 hover:text-primary-900"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        ))}

        {/* Amenities */}
        {filters.amenities?.map(amenity => (
          <div key={amenity} className="flex items-center bg-primary-100 text-primary-700 px-3 py-1 rounded-full text-sm">
            <span>{amenity}</span>
            <button
              onClick={() => handleAmenityChange(amenity)}
              className="ml-2 hover:text-primary-900"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        ))}

        {/* Radius */}
        {filters.radius && (
          <div className="flex items-center bg-primary-100 text-primary-700 px-3 py-1 rounded-full text-sm">
            <MapPin className="w-4 h-4 mr-1" />
            <span>{filters.radius}km radius</span>
            <button
              onClick={() => onFiltersChange({ radius: undefined })}
              className="ml-2 hover:text-primary-900"
            >
              <X className="w-3 h-3" />
            </button>
          </div>
        )}

        {/* Clear All */}
        {activeFiltersCount > 0 && (
          <button
            onClick={clearFilters}
            className="text-gray-500 hover:text-gray-700 text-sm px-3 py-1 rounded-full hover:bg-gray-100"
          >
            Clear all
          </button>
        )}
      </div>

      {/* Expandable Filters */}
      <div className="border border-gray-200 rounded-lg">
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors duration-200"
        >
          <div className="flex items-center space-x-2">
            <Filter className="w-5 h-5 text-gray-600" />
            <span className="font-medium text-gray-900">More Filters</span>
            {activeFiltersCount > 0 && (
              <span className="bg-primary-500 text-white text-xs px-2 py-1 rounded-full">
                {activeFiltersCount}
              </span>
            )}
          </div>
          <ChevronDown 
            className={`w-5 h-5 text-gray-600 transition-transform duration-200 ${
              isExpanded ? 'rotate-180' : ''
            }`} 
          />
        </button>

        <AnimatePresence>
          {isExpanded && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.3 }}
              className="overflow-hidden"
            >
              <div className="p-4 border-t border-gray-200 space-y-6">
                {/* Price Range */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Price Range (per month)
                  </label>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <input
                        type="number"
                        placeholder="Min"
                        value={filters.priceMin || ''}
                        onChange={(e) => handlePriceChange('priceMin', e.target.value)}
                        className="input"
                      />
                    </div>
                    <div>
                      <input
                        type="number"
                        placeholder="Max"
                        value={filters.priceMax || ''}
                        onChange={(e) => handlePriceChange('priceMax', e.target.value)}
                        className="input"
                      />
                    </div>
                  </div>
                </div>

                {/* Bedrooms & Bathrooms */}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Bedrooms
                    </label>
                    <select
                      value={filters.bedrooms || ''}
                      onChange={(e) => handleBedroomsChange(e.target.value)}
                      className="input"
                    >
                      <option value="">Any</option>
                      <option value="1">1+</option>
                      <option value="2">2+</option>
                      <option value="3">3+</option>
                      <option value="4">4+</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Bathrooms
                    </label>
                    <select
                      value={filters.bathrooms || ''}
                      onChange={(e) => handleBathroomsChange(e.target.value)}
                      className="input"
                    >
                      <option value="">Any</option>
                      <option value="1">1+</option>
                      <option value="2">2+</option>
                      <option value="3">3+</option>
                      <option value="4">4+</option>
                    </select>
                  </div>
                </div>

                {/* Property Type */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Property Type
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {propertyTypes.map(type => (
                      <label key={type.value} className="flex items-center">
                        <input
                          type="checkbox"
                          checked={filters.propertyType?.includes(type.value) || false}
                          onChange={() => handlePropertyTypeChange(type.value)}
                          className="rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                        />
                        <span className="ml-2 text-sm text-gray-700">{type.label}</span>
                      </label>
                    ))}
                  </div>
                </div>

                {/* Amenities */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Amenities
                  </label>
                  <div className="grid grid-cols-3 gap-2">
                    {amenities.map(amenity => (
                      <label key={amenity} className="flex items-center">
                        <input
                          type="checkbox"
                          checked={filters.amenities?.includes(amenity) || false}
                          onChange={() => handleAmenityChange(amenity)}
                          className="rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                        />
                        <span className="ml-2 text-sm text-gray-700">{amenity}</span>
                      </label>
                    ))}
                  </div>
                </div>

                {/* Search Radius */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Search Radius (km)
                  </label>
                  <select
                    value={filters.radius || ''}
                    onChange={(e) => handleRadiusChange(e.target.value)}
                    className="input"
                  >
                    <option value="">Any distance</option>
                    <option value="1">1 km</option>
                    <option value="5">5 km</option>
                    <option value="10">10 km</option>
                    <option value="25">25 km</option>
                    <option value="50">50 km</option>
                  </select>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}
