import { useEffect, useRef, useState } from 'react'
import { motion } from 'framer-motion'
import mapboxgl from 'mapbox-gl'
import 'mapbox-gl/dist/mapbox-gl.css'
import { formatCurrency } from '@/utils'
import type { Property } from '@/types'

interface MapViewProps {
  properties: Property[]
  selectedProperty?: Property | null
  center?: [number, number] // [longitude, latitude]
  radius?: number
  onPropertySelect?: (property: Property) => void
}

export default function MapView({
  properties,
  selectedProperty,
  center,
  radius,
  onPropertySelect,
}: MapViewProps) {
  const mapContainer = useRef<HTMLDivElement>(null)
  const map = useRef<mapboxgl.Map | null>(null)
  const markers = useRef<mapboxgl.Marker[]>([])
  const [isLoaded, setIsLoaded] = useState(false)

  // Initialize map
  useEffect(() => {
    if (!mapContainer.current || map.current) return

    const mapboxToken = (import.meta as any).env?.VITE_MAPBOX_ACCESS_TOKEN || 'pk.eyJ1IjoiY3JpYmx5IiwiYSI6ImNsZXhhbXBsZTAwMDAzM3BqZ2V6dGJ6dG8ifQ.example'

    mapboxgl.accessToken = mapboxToken

    map.current = new mapboxgl.Map({
      container: mapContainer.current,
      style: 'mapbox://styles/mapbox/light-v11',
      center: center || [-74.006, 40.7128], // Default to NYC
      zoom: 12,
      attributionControl: false,
    })

    map.current.on('load', () => {
      setIsLoaded(true)
    })

    // Add navigation control
    map.current.addControl(new mapboxgl.NavigationControl(), 'top-right')

    return () => {
      if (map.current) {
        map.current.remove()
        map.current = null
      }
    }
  }, [])

  // Update map center when center prop changes
  useEffect(() => {
    if (map.current && center) {
      map.current.flyTo({
        center,
        zoom: radius ? Math.max(10, 15 - radius / 2) : 12,
        duration: 1000,
      })
    }
  }, [center, radius])

  // Add/update markers
  useEffect(() => {
    if (!map.current || !isLoaded) return

    // Clear existing markers
    markers.current.forEach(marker => marker.remove())
    markers.current = []

    // Add markers for each property
    properties.forEach((property) => {
      const markerElement = document.createElement('div')
      markerElement.className = 'property-marker'
      markerElement.innerHTML = `
        <div class="relative">
          <div class="w-8 h-8 bg-primary-500 rounded-full border-2 border-white shadow-lg flex items-center justify-center cursor-pointer hover:scale-110 transition-transform duration-200">
            <span class="text-white font-bold text-sm">$${Math.floor(property.price / 1000)}k</span>
          </div>
          ${selectedProperty?.id === property.id ? '<div class="absolute -inset-1 bg-primary-500 rounded-full animate-ping"></div>' : ''}
        </div>
      `

      const marker = new mapboxgl.Marker(markerElement)
        .setLngLat([property.longitude, property.latitude])
        .addTo(map.current!)

      marker.getElement().addEventListener('click', () => {
        onPropertySelect?.(property)
      })

      markers.current.push(marker)
    })
  }, [properties, selectedProperty, isLoaded, onPropertySelect])

  // Add radius circle if radius is specified
  useEffect(() => {
    if (!map.current || !isLoaded || !center || !radius) return

    // For now, we'll skip the radius circle implementation
    // This would require turf.js for proper circle generation
    // In a production app, you'd want to implement this properly
  }, [center, radius, isLoaded])

  return (
    <div className="relative h-full">
      <div ref={mapContainer} className="w-full h-full" />
      
      {/* Map Loading Overlay */}
      {!isLoaded && (
        <div className="absolute inset-0 bg-gray-100 flex items-center justify-center">
          <div className="text-center">
            <div className="w-8 h-8 border-2 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto mb-2"></div>
            <p className="text-sm text-gray-600">Loading map...</p>
          </div>
        </div>
      )}

      {/* Map Controls */}
      <div className="absolute top-4 left-4 z-10">
        <div className="bg-white rounded-lg shadow-lg p-2">
          <div className="text-xs text-gray-600 mb-1">Search Radius</div>
          <div className="text-sm font-semibold text-primary-600">
            {radius ? `${radius}km` : 'All areas'}
          </div>
        </div>
      </div>

      {/* Property Info Popup */}
      {selectedProperty && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="absolute bottom-4 left-4 right-4 z-10"
        >
          <div className="bg-white rounded-lg shadow-lg p-4 border border-gray-200">
            <div className="flex items-start space-x-3">
              <div className="w-16 h-16 bg-gray-200 rounded-lg flex-shrink-0 overflow-hidden">
                {selectedProperty.images.length > 0 ? (
                  <img
                    src={selectedProperty.images[0]}
                    alt={selectedProperty.title}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full bg-primary-100 flex items-center justify-center">
                    <span className="text-primary-500 text-lg">🏠</span>
                  </div>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-gray-900 truncate">
                  {selectedProperty.title}
                </h3>
                <p className="text-sm text-gray-600 mb-1">
                  {selectedProperty.city}, {selectedProperty.state}
                </p>
                <div className="flex items-center justify-between">
                  <div className="text-lg font-bold text-primary-600">
                    {formatCurrency(selectedProperty.price, selectedProperty.currency)}/mo
                  </div>
                  <div className="flex items-center space-x-2 text-sm text-gray-500">
                    <span>{selectedProperty.bedrooms} bed</span>
                    <span>•</span>
                    <span>{selectedProperty.bathrooms} bath</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </div>
  )
}

// Add CSS for custom markers
const style = document.createElement('style')
style.textContent = `
  .property-marker {
    cursor: pointer;
  }
  
  .mapboxgl-popup-content {
    padding: 0;
    border-radius: 12px;
    box-shadow: 0 10px 25px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  }
  
  .mapboxgl-popup-tip {
    border-top-color: white;
  }
`
document.head.appendChild(style)
