import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { MapPin, Filter, Grid, Map as MapIcon } from 'lucide-react'
import { Button } from '@/components/ui/Button'
import MapView from '@/components/MapView'
import PropertyCard from '@/components/PropertyCard'
import SearchFilters from '@/components/SearchFilters'
import { useProperties, useGeolocation } from '@/hooks'
import { useUIStore } from '@/stores'
import type { Property, ExploreFilters } from '@/types'

export default function ExplorePage() {
  const [filters, setFilters] = useState<ExploreFilters>({})
  const [selectedProperty, setSelectedProperty] = useState<Property | null>(null)
  const { viewMode, setViewMode } = useUIStore()
  const { location } = useGeolocation()
  
  const { properties, isLoading, error, hasMore, loadMore } = useProperties(filters)

  // Set user location as default search center
  useEffect(() => {
    if (location && !filters.latitude) {
      setFilters(prev => ({
        ...prev,
        latitude: location.latitude,
        longitude: location.longitude,
        radius: 10, // 10km default radius
      }))
    }
  }, [location, filters.latitude])

  const handleFilterChange = (newFilters: Partial<ExploreFilters>) => {
    setFilters(prev => ({ ...prev, ...newFilters }))
  }

  const handlePropertySelect = (property: Property) => {
    setSelectedProperty(property)
  }

  return (
    <div className="min-h-screen bg-background">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 sticky top-16 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <h1 className="text-2xl font-bold text-gray-900">Explore Properties</h1>
              <div className="hidden sm:flex items-center space-x-2 text-sm text-gray-500">
                <MapPin className="w-4 h-4" />
                <span>
                  {properties.length} properties found
                  {filters.radius && ` within ${filters.radius}km`}
                </span>
              </div>
            </div>

            <div className="flex items-center space-x-3">
              {/* View Mode Toggle */}
              <div className="flex items-center bg-gray-100 rounded-lg p-1">
                <button
                  onClick={() => setViewMode('grid')}
                  className={`p-2 rounded-md transition-colors duration-200 ${
                    viewMode === 'grid'
                      ? 'bg-white text-primary-600 shadow-sm'
                      : 'text-gray-600 hover:text-gray-900'
                  }`}
                >
                  <Grid className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setViewMode('map')}
                  className={`p-2 rounded-md transition-colors duration-200 ${
                    viewMode === 'map'
                      ? 'bg-white text-primary-600 shadow-sm'
                      : 'text-gray-600 hover:text-gray-900'
                  }`}
                >
                  <MapIcon className="w-4 h-4" />
                </button>
              </div>

              {/* Filters Button */}
              <Button variant="outline" size="sm">
                <Filter className="w-4 h-4 mr-2" />
                Filters
              </Button>
            </div>
          </div>

          {/* Search Filters */}
          <div className="mt-4">
            <SearchFilters
              filters={filters}
              onFiltersChange={handleFilterChange}
            />
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex h-[calc(100vh-200px)]">
        {/* Properties List */}
        <div className={`${viewMode === 'map' ? 'w-1/2' : 'w-full'} overflow-y-auto`}>
          <div className="p-4 sm:p-6">
            {isLoading ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {[...Array(6)].map((_, i) => (
                  <div key={i} className="animate-pulse">
                    <div className="bg-gray-200 rounded-2xl h-64 mb-4"></div>
                    <div className="space-y-2">
                      <div className="bg-gray-200 h-4 rounded w-3/4"></div>
                      <div className="bg-gray-200 h-4 rounded w-1/2"></div>
                      <div className="bg-gray-200 h-4 rounded w-1/3"></div>
                    </div>
                  </div>
                ))}
              </div>
            ) : error ? (
              <div className="text-center py-12">
                <div className="text-red-500 mb-4">Error loading properties</div>
                <Button onClick={() => window.location.reload()}>
                  Try Again
                </Button>
              </div>
            ) : properties.length === 0 ? (
              <div className="text-center py-12">
                <div className="text-gray-500 mb-4">No properties found</div>
                <p className="text-gray-400">Try adjusting your filters</p>
              </div>
            ) : (
              <>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {properties.map((property: Property, index: number) => (
                    <motion.div
                      key={property.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.3, delay: index * 0.1 }}
                    >
                      <PropertyCard
                        property={property}
                        onClick={() => handlePropertySelect(property)}
                        isSelected={selectedProperty?.id === property.id}
                      />
                    </motion.div>
                  ))}
                </div>

                {/* Load More */}
                {hasMore && (
                  <div className="text-center mt-8">
                    <Button
                      onClick={loadMore}
                      variant="outline"
                      isLoading={isLoading}
                    >
                      Load More Properties
                    </Button>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* Map View */}
        {viewMode === 'map' && (
          <div className="w-1/2 sticky top-0">
            <MapView
              properties={properties}
              selectedProperty={selectedProperty}
              center={filters.latitude && filters.longitude ? [filters.longitude, filters.latitude] : undefined}
              radius={filters.radius}
              onPropertySelect={handlePropertySelect}
            />
          </div>
        )}
      </div>

      {/* Mobile Map Toggle */}
      <div className="lg:hidden fixed bottom-6 right-6 z-40">
        <Button
          onClick={() => setViewMode(viewMode === 'grid' ? 'map' : 'grid')}
          className="rounded-full w-14 h-14 shadow-lg"
        >
          {viewMode === 'grid' ? <MapIcon className="w-6 h-6" /> : <Grid className="w-6 h-6" />}
        </Button>
      </div>
    </div>
  )
}
