import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { User, Property, ExploreFilters, ChatMessage, Notification } from '@/types'

// Auth Store
interface AuthStore {
  user: User | null
  accessToken: string | null
  refreshToken: string | null
  isAuthenticated: boolean
  isLoading: boolean
  error: string | null
  
  // Actions
  setUser: (user: User) => void
  setTokens: (accessToken: string, refreshToken: string) => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
  login: (user: User, accessToken: string, refreshToken: string) => void
  logout: () => void
  clearError: () => void
}

export const useAuthStore = create<AuthStore>()(
  persist(
    (set) => ({
      user: null,
      accessToken: null,
      refreshToken: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,

      setUser: (user) => set({ user }),
      setTokens: (accessToken, refreshToken) => set({ accessToken, refreshToken }),
      setLoading: (isLoading) => set({ isLoading }),
      setError: (error) => set({ error }),
      
      login: (user, accessToken, refreshToken) => set({
        user,
        accessToken,
        refreshToken,
        isAuthenticated: true,
        error: null,
      }),
      
      logout: () => set({
        user: null,
        accessToken: null,
        refreshToken: null,
        isAuthenticated: false,
        error: null,
      }),
      
      clearError: () => set({ error: null }),
    }),
    {
      name: 'auth-storage',
      partialize: (state) => ({
        user: state.user,
        accessToken: state.accessToken,
        refreshToken: state.refreshToken,
        isAuthenticated: state.isAuthenticated,
      }),
    }
  )
)

// Explore Store
interface ExploreStore {
  properties: Property[]
  filters: ExploreFilters
  isLoading: boolean
  error: string | null
  hasMore: boolean
  page: number
  
  // Actions
  setProperties: (properties: Property[]) => void
  addProperties: (properties: Property[]) => void
  setFilters: (filters: Partial<ExploreFilters>) => void
  clearFilters: () => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
  setHasMore: (hasMore: boolean) => void
  setPage: (page: number) => void
  reset: () => void
}

export const useExploreStore = create<ExploreStore>((set) => ({
  properties: [],
  filters: {},
  isLoading: false,
  error: null,
  hasMore: true,
  page: 1,

  setProperties: (properties) => set({ properties }),
  addProperties: (properties) => set((state) => ({
    properties: [...state.properties, ...properties]
  })),
  setFilters: (filters) => set((state) => ({
    filters: { ...state.filters, ...filters },
    page: 1,
    properties: [],
  })),
  clearFilters: () => set({ filters: {}, page: 1, properties: [] }),
  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),
  setHasMore: (hasMore) => set({ hasMore }),
  setPage: (page) => set({ page }),
  reset: () => set({
    properties: [],
    filters: {},
    isLoading: false,
    error: null,
    hasMore: true,
    page: 1,
  }),
}))

// Favorites Store
interface FavoritesStore {
  favorites: Property[]
  isLoading: boolean
  error: string | null
  
  // Actions
  setFavorites: (favorites: Property[]) => void
  addFavorite: (property: Property) => void
  removeFavorite: (propertyId: string) => void
  toggleFavorite: (property: Property) => void
  isFavorite: (propertyId: string) => boolean
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
}

export const useFavoritesStore = create<FavoritesStore>((set, get) => ({
  favorites: [],
  isLoading: false,
  error: null,

  setFavorites: (favorites) => set({ favorites }),
  addFavorite: (property) => set((state) => ({
    favorites: [...state.favorites, property]
  })),
  removeFavorite: (propertyId) => set((state) => ({
    favorites: state.favorites.filter(p => p.id !== propertyId)
  })),
  toggleFavorite: (property) => {
    const state = get()
    if (state.isFavorite(property.id)) {
      state.removeFavorite(property.id)
    } else {
      state.addFavorite(property)
    }
  },
  isFavorite: (propertyId: string): boolean => {
    const state = get()
    return state.favorites.some((p: Property) => p.id === propertyId)
  },
  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),
}))

// Chat Store
interface ChatStore {
  conversations: any[]
  activeConversation: string | null
  messages: Record<string, ChatMessage[]>
  unreadCount: number
  isLoading: boolean
  error: string | null
  
  // Actions
  setConversations: (conversations: any[]) => void
  setActiveConversation: (conversationId: string | null) => void
  setMessages: (conversationId: string, messages: ChatMessage[]) => void
  addMessage: (conversationId: string, message: ChatMessage) => void
  setUnreadCount: (count: number) => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
}

export const useChatStore = create<ChatStore>((set) => ({
  conversations: [],
  activeConversation: null,
  messages: {},
  unreadCount: 0,
  isLoading: false,
  error: null,

  setConversations: (conversations) => set({ conversations }),
  setActiveConversation: (activeConversation) => set({ activeConversation }),
  setMessages: (conversationId, messages) => set((state) => ({
    messages: { ...state.messages, [conversationId]: messages }
  })),
  addMessage: (conversationId, message) => set((state) => ({
    messages: {
      ...state.messages,
      [conversationId]: [...(state.messages[conversationId] || []), message]
    }
  })),
  setUnreadCount: (unreadCount) => set({ unreadCount }),
  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),
}))

// Notifications Store
interface NotificationsStore {
  notifications: Notification[]
  unreadCount: number
  isLoading: boolean
  error: string | null
  
  // Actions
  setNotifications: (notifications: Notification[]) => void
  addNotification: (notification: Notification) => void
  markAsRead: (notificationId: string) => void
  markAllAsRead: () => void
  setUnreadCount: (count: number) => void
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
}

export const useNotificationsStore = create<NotificationsStore>((set) => ({
  notifications: [],
  unreadCount: 0,
  isLoading: false,
  error: null,

  setNotifications: (notifications) => set({ notifications }),
  addNotification: (notification) => set((state) => ({
    notifications: [notification, ...state.notifications]
  })),
  markAsRead: (notificationId) => set((state) => ({
    notifications: state.notifications.map(n => 
      n.id === notificationId ? { ...n, isRead: true } : n
    ),
    unreadCount: Math.max(0, state.unreadCount - 1),
  })),
  markAllAsRead: () => set((state) => ({
    notifications: state.notifications.map(n => ({ ...n, isRead: true })),
    unreadCount: 0,
  })),
  setUnreadCount: (unreadCount) => set({ unreadCount }),
  setLoading: (isLoading) => set({ isLoading }),
  setError: (error) => set({ error }),
}))

// UI Store
interface UIStore {
  sidebarOpen: boolean
  theme: 'light' | 'dark'
  viewMode: 'grid' | 'map'
  selectedFilters: string[]
  
  // Actions
  toggleSidebar: () => void
  setSidebarOpen: (open: boolean) => void
  setTheme: (theme: 'light' | 'dark') => void
  setViewMode: (mode: 'grid' | 'map') => void
  toggleFilter: (filter: string) => void
  clearFilters: () => void
}

export const useUIStore = create<UIStore>()(
  persist(
    (set) => ({
      sidebarOpen: false,
      theme: 'light',
      viewMode: 'grid',
      selectedFilters: [],

      toggleSidebar: () => set((state) => ({ sidebarOpen: !state.sidebarOpen })),
      setSidebarOpen: (sidebarOpen) => set({ sidebarOpen }),
      setTheme: (theme) => set({ theme }),
      setViewMode: (viewMode) => set({ viewMode }),
      toggleFilter: (filter) => set((state) => ({
        selectedFilters: state.selectedFilters.includes(filter)
          ? state.selectedFilters.filter(f => f !== filter)
          : [...state.selectedFilters, filter]
      })),
      clearFilters: () => set({ selectedFilters: [] }),
    }),
    {
      name: 'ui-storage',
    }
  )
)
